"""Redactar tablas desde resultados efectivamente obtenidos. No ejecuta CAD ni pruebas."""
from pathlib import Path
import json
H=Path(__file__).resolve().parent
load=lambda n:json.loads((H/n).read_text(encoding='utf-8'))
r=load('resistencia_v09.json');st=load('estatica_v09.json');motion=load('informe_movimiento_v09.json')
p=r['peaks'];s=r['static_peaks']
fmt=lambda v:f'{v:,.2f}'.replace(',','@').replace('.',',').replace('@','.')
